// Extraction et nettoyage.
// L'URL de la source est obligatoire : l'API refuse tout candidat sans elle,
// et elle sert aussi d'empreinte de déduplication d'un passage à l'autre.
return items
  .filter((item) => item.json.link)
  .map((item) => ({
    json: {
      name: (item.json.title || '').trim(),
      source_url: item.json.link,
      source_name: 'À renseigner : nom de la source',
      payload: {
        description: (item.json.contentSnippet || '').trim(),
      },
    },
  }));

// Classification : catégorie, pays éligibles, types de projet, montants, date limite.
// Règle absolue : ne JAMAIS compléter un champ absent de la source. Un champ
// vide devient « Information non fournie » côté produit ; un champ inventé
// devient une erreur dans le dossier de financement d'un auteur.
// Les dates illisibles sont écartées par l'API, pas devinées.
return items.map((item) => ({
  json: {
    ...item.json,
    payload: {
      ...item.json.payload,
      // organization: '...',   // à remplir si la source le dit
      // deadline: 'AAAA-MM-JJ',
      // category: 'FUND',
    },
  },
}));
